function validate([points]) {
  if (points.length < 2 || points.length > 100000) return 'points needs 2 to 10^5 points.';
  for (const point of points) {
    if (point.length !== 2) return 'Each point is a pair [x, y].';
    if (point.some(value => value < 0 || value > 1000000000)) return 'Coordinates are between 0 and 10^9.';
  }
  return null;
}

