function maxWidthOfVerticalArea(points) {
  // For every x, find the next larger x among all points; the empty strip between them is a candidate.
  let widest = 0;
  for (const [x] of points) {
    let next = Infinity;
    for (const [other] of points) {
      if (other > x && other < next) next = other;
    }
    if (next !== Infinity) widest = Math.max(widest, next - x);
  }
  return widest;
}

