function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 2000 : 2 + pick(7);
  const r = rand();
  // Narrow ranges give repeated x values; wide ranges give big gaps.
  const span = r < 0.3 ? 1 + pick(size === 'large' ? 5000 : 6) : r < 0.6 ? 1000 : 1000000001;
  const points = Array.from({ length: n }, () => [pick(span), pick(1000000001)]);
  return [points];
}
